components.calculateValue:
const toNumberOrZero = v => Number.isFinite(v) ? v : 0;

const eigenWoningBlocks = Array.isArray(data.vastgesteldeEigenWoning)
  ? data.vastgesteldeEigenWoning.filter(Boolean)
  : [];

const components = eigenWoningBlocks.flatMap(b =>
  Array.isArray(b.componenten) ? b.componenten.filter(Boolean) : []
);

const sumBy = (rows, predicate) =>
  rows.reduce((sum, row) => sum + (predicate(row) ? toNumberOrZero(row.waarde) : 0), 0);

const woz = sumBy(components, r => r?.soortVermogenscomponent?.code === '1');
const hypotheek = sumBy(components, r => r?.soortVermogenscomponent?.code === '17');
const levensBelegging = sumBy(components, r => r?.soortVermogenscomponent?.code === '15');
const buitenBeschouwing = eigenWoningBlocks.reduce((sum, b) => sum + toNumberOrZero(b.vrijlating), 0);
const beschikbaar = woz - hypotheek + levensBelegging - buitenBeschouwing;

const toelichting =
  components.find(r => typeof r?.toelichting === 'string' && r.toelichting.trim())?.toelichting || '';

value = { woz, hypotheek, levensBelegging, buitenBeschouwing, beschikbaar, toelichting };
